SELECT COUNT(1)
FROM platform_access_client


        AND client_code LIKE CONCAT(#{clientCode}, '%')


        AND status = #{status}


        AND allow_issue = #{allowIssue}

SELECT id, client_code AS clientCode, client_name AS clientName,
       status, allow_issue AS allowIssue, remark,
       created_at AS createdAt, updated_at AS updatedAt
FROM platform_access_client


        AND client_code LIKE CONCAT(#{clientCode}, '%')


        AND status = #{status}


        AND allow_issue = #{allowIssue}


ORDER BY id DESC
LIMIT #{offset}, #{limit}
